def card(work):
    WESTERN, INDIC = (set('0123456789'), set('٠١٢٣٤٥٦٧٨٩'))

    def wrap_ltr(html_text):
        return re.sub('([A-Za-z][A-Za-z0-9 .:/_-]*[A-Za-z0-9])', '<bdi>\\1</bdi>', html_text)

    def numerals(text):
        has_w, has_i = (bool(set(text) & WESTERN), bool(set(text) & INDIC))
        return 'mixed' if has_w and has_i else 'western' if has_w else 'indic' if has_i else 'none'
    p = 'استخدم أمر git push ثم افتح GitHub Actions.'
    out = wrap_ltr(p)
    html = f'<html lang="ar" dir="rtl"><p>{out}</p><p dir="ltr">English line</p></html>'
    _w(work, 'mixed.html', html)
    runs_docx = [('مرحبا ', True), ('Kosif', False), (' بك', True)]
    return [_c('each LTR run isolated in <bdi>', out == 'استخدم أمر <bdi>git push</bdi> ثم افتح <bdi>GitHub Actions</bdi>.', out), _c('mixed numeral systems detected', numerals('الصفحة 12 من ١٥') == 'mixed', ''), _c('one system per document passes', numerals('الصفحة ١٢ من ١٥') == 'indic' and numerals('page 12 of 15') == 'western', ''), _c('DOCX: LTR run kept without w:rtl', [r for r, rtl in runs_docx if not rtl] == ['Kosif'], runs_docx)]
